      const attributes = interactive ? ` data-record="${escapeHtml(record.id)}" data-category="${escapeHtml(record.category)}" data-search="${escapeHtml(search)}" tabindex="0"` : "";
      return `<tr${attributes}><td><span class="pill neutral">${escapeHtml(record.category)}</span> ${escapeHtml(objectName(record))}<br>${escapeHtml(address(record))}<br>${escapeHtml(record.section)}</td><td>${escapeHtml(explanation(record))}${record.gap ? "<br><strong>\u6B64\u6761\u662F\u7531\u8303\u56F4 / \u660E\u7EC6\u6838\u5BF9\u63ED\u793A\u7684\u7F3A\u53E3\uFF0C\u4E0D\u662F\u65B0\u589E\u4E0A\u6E38\u7ED3\u8BBA\u3002</strong>" : ""}</td><td>\u4E1A\u52A1\u5F71\u54CD\u672A\u63D0\u4F9B<br>\u8D23\u4EFB\u4EBA\u672A\u63D0\u4F9B<br>\u5904\u7F6E\u4F18\u5148\u7EA7\u672A\u63D0\u4F9B</td><td>${recordPills(record)}${interactive ? `<br><button type="button" class="btn" data-open-evidence="${escapeHtml(record.id)}">\u67E5\u770B\u8BC1\u636E\u8BE6\u60C5</button>` : ""}</td></tr>`;
    }).join("")}</tbody></table></div>`;
  }
  function evidence2(record, interactive, first) {
    const item = record.source, facts = object(item.facts), observedState = object(facts.stateEvidence ?? item.stateEvidence);
    const attributes = interactive ? ` data-evidence-panel="${escapeHtml(record.id)}"${first ? "" : " hidden"}` : "";
    const limitations = record.category === "\u4E1A\u52A1" ? "\u8BA1\u7B97\u8DEF\u5F84\u3001\u7B56\u7565\u7ED3\u679C\u4E0E\u4E1A\u52A1\u5E94\u7528\u5B9E\u9645\u54CD\u5E94\u662F\u4E0D\u540C\u8BC1\u636E\uFF1B\u672A\u6267\u884C\u4E3B\u52A8\u63A2\u6D4B\u3002" : record.category === "\u6F0F\u6D1E" ? "\u6309SOC\u5DF2\u6709\u6F0F\u6D1E\u6570\u636E\u5448\u73B0\uFF1B\u5B8C\u6574\u6210\u529F\u7684\u7A7A\u7ED3\u679C\u4E3A\u6CA1\u6709\u6F0F\u6D1E\uFF0C\u8BFB\u53D6\u5931\u8D25\u6216\u672A\u5B8C\u6210\u5355\u72EC\u4FDD\u7559\u3002" : record.category === "\u57FA\u7EBF" ? "\u8BFB\u53D6\u62A5\u544A\u6807\u5FD7\u4E0D\u8BC1\u660E\u6A21\u677F\u5185\u5BB9\u7248\u672C\u4E0E\u62A5\u544A\u65F6\u6548\uFF1B\u672A\u8FD4\u56DE\u6A21\u677F\u6216\u62A5\u544A\u4E0D\u80FD\u89C6\u4E3A\u901A\u8FC7\u3001\u4E0D\u9002\u7528\u3002" : record.category === "\u8BBE\u5907" ? "\u9ED8\u8BA4SOC\u6570\u636E\u4E3A\u6700\u65B0\uFF0C\u76F4\u63A5\u5448\u73B0SOC\u5728\u7EBF\u6216\u79BB\u7EBF\u72B6\u6001\uFF1Bunknown\u663E\u793ASOC\u672A\u91C7\u96C6\u5230\u72B6\u6001\u6570\u636E\uFF0C\u4E0D\u5728\u672C\u7AEF\u56E0\u65F6\u95F4\u6216\u5FC3\u8DF3\u6539\u5224\u3002" : "\u4EC5\u4FDD\u7559\u5DF2\u77E5\u53EF\u5C55\u793A\u5B57\u6BB5\uFF1B\u6CA1\u6709\u63D0\u4F9B\u7684\u4E8B\u5B9E\u4E0D\u4F5C\u8865\u9F50\u3002";
    return `<section class="card"${attributes}><h3${interactive ? ' tabindex="-1"' : ""}>\u8BC1\u636E\u8BE6\u60C5 \xB7 ${escapeHtml(objectName(record))} ${recordPills(record)}</h3><dl class="grid two"><div><dt>\u68C0\u67E5\u7EF4\u5EA6</dt><dd>${escapeHtml(record.section)}</dd></div><div><dt>\u7A33\u5B9A\u8EAB\u4EFD / \u5730\u5740</dt><dd>${escapeHtml(address(record))}</dd></div><div><dt>\u672C\u6B21\u8BFB\u53D6\u65F6\u95F4</dt><dd>${shown(item.observed_at)}</dd></div><div><dt>\u4E0A\u6E38\u89C2\u6D4B\u65F6\u95F4</dt><dd>${shown(facts.lastSeenAt ?? facts.lastProbeAt, "\u5F53\u524D\u7ED3\u679C\u672A\u63D0\u4F9B\u72EC\u7ACB\u4E0A\u6E38\u89C2\u6D4B\u65F6\u95F4\uFF1B\u9010\u4FE1\u53F7 observedAt \u89C1\u5B89\u5168\u8BC1\u636E")}</dd></div><div><dt>SOC \u72B6\u6001\u8BC4\u4F30\u65F6\u95F4 / \u65F6\u95F4\u57FA\u51C6</dt><dd>${shown(observedState.evaluatedAt)} / ${shown(observedState.timeBasis)}</dd></div></dl><p>${escapeHtml(explanation(record))}</p><p>${escapeHtml(limitations)}</p>${present(item.recommendation) ? `<p><strong>\u6765\u6E90\u5EFA\u8BAE \xB7 \u5EFA\u8BAE\uFF0C\u672A\u6267\u884C\uFF1A</strong>${escapeHtml(item.recommendation)}</p>` : "<p>\u672A\u63D0\u4F9B\u9488\u5BF9\u6027\u5904\u7F6E\u5EFA\u8BAE\uFF1B\u4E0D\u636E\u7ED3\u679C\u8BF4\u660E\u81EA\u52A8\u5224\u65AD\u6839\u56E0\u3002</p>"}<p>\u4E1A\u52A1\u5F71\u54CD\u3001\u8D23\u4EFB\u4EBA\u548C\u4F18\u5148\u7EA7\u672A\u63D0\u4F9B\u3002${record.gap ? "\u4EE5\u4E0B\u4EC5\u4E3A\u5C55\u793A\u5C42\u7F3A\u53E3\u8BF4\u660E\uFF0C\u4E0D\u4F2A\u88C5\u4E3A\u6765\u6E90\u68C0\u67E5\u6761\u76EE\u3002" : "\u4EE5\u4E0B\u4E3A\u5B8C\u6574\u7684\u5DF2\u77E5\u5B57\u6BB5\u5B89\u5168\u6295\u5F71\uFF0C\u4E0D\u662F\u5B8C\u6574\u539F\u59CB\u54CD\u5E94\uFF1B\u672A\u77E5 / \u654F\u611F\u5B57\u6BB5\u4E0D\u8F93\u51FA\u3002"}</p><pre>${jsonText(safeProjection(item))}</pre></section>`;
  }
