  const printableDetails = `<section class="card"><h2>\u5168\u91CF\u68C0\u67E5\u660E\u7EC6 \xB7 \u72EC\u7ACB\u6253\u5370</h2><p>\u4EE5\u4E0B\u6309\u5B8C\u6574\u5217\u8868\u751F\u6210\uFF0C\u5305\u542B\u6B63\u5E38\u3001\u5F02\u5E38\u3001\u672A\u77E5\u3001\u5931\u8D25\u3001\u4E0D\u9002\u7528\u4E0E\u6D3E\u751F\u7F3A\u53E3\uFF0C\u4E0D\u4F9D\u8D56\u9875\u9762\u5F53\u524D\u641C\u7D22\u6216\u9009\u4E2D\u72B6\u6001\u3002</p>${detailTable(allRecords, false)}</section>${allRecords.map((record) => evidence2(record, false, false)).join("")}`;
